export const CAREEM_TAXONOMY_EVIDENCE = DATA.evidence;

const BRAND_POOLS: Record<string,string[]> = {"groceries":["Kareebu Select","Nile Pantry","Savanna Fresh","Daily Basket"],"shops":["Kareebu Select","City Market","Everyday Store","Urban Supply"],"electronics":["Kareebu Tech","VoltEdge","NovaTech","GridOne"],"home-care":["Kareebu Care","HomePro","CareCrew","Urban Home"],"fix":["Kareebu Fix","FixPro","Repair Crew","HomeTech"],"dineout":["The Pearl Table","Nile Terrace","Kampala Social","Mizizi Kitchen","Ember & Grain","Garden City Bistro","Saffron House","Lemongrass Table","Acacia Dining Room","The Copper Pot","Terrace 54","Savanna Table"],"food":["Kareebu Eats","City Kitchen","Local Plate","Fresh Table"]};
const PRICE_BANDS: Record<string,[number,number]> = {"food":[8000,65000],"dineout":[20000,140000],"groceries":[3000,120000],"shops":[5000,320000],"electronics":[15000,1600000],"home-care":[15000,300000],"fix":[15000,450000]};

function stableHash(value: string) {
  let h=2166136261;
  for(let i=0;i<value.length;i+=1) {
    h ^= value.charCodeAt(i);
    h=Math.imul(h,16777619);
  }
  return h>>>0;
}

function priceFor(domainId: string, subcategoryId: string, index: number) {
  const [low,high]=PRICE_BANDS[domainId] ?? [5000,100000];
  const ratio=Math.pow((stableHash(`${subcategoryId}:${index}`)%1000)/999,1.8);
  const value=low+(high-low)*ratio;
  const step=value<10000?500:value<100000?1000:5000;
  return Math.round(value/step)*step;
}

function namesFor(domainId: string, title: string) {
  if(domainId==='food') return [`Classic ${title}`,`Signature ${title}`,`${title} Combo`];
  if(domainId==='dineout') return [`${title} Experience`,`${title} for Two`,`Premium ${title}`];
  if(domainId==='home-care'||domainId==='fix') return [`${title} - Standard`,`${title} - Plus`,`${title} - Premium`];
  if(domainId==='electronics') return [`Essential ${title}`,`${title} Pro`,`Premium ${title}`];
  return [`Everyday ${title}`,`${title} Value Pack`,`Premium ${title}`];
}

function itemType(domainId: string): UnifiedCatalogItem['type'] {
  if(domainId==='food') return 'dish';
  if(domainId==='dineout') return 'experience';
  if(domainId==='home-care'||domainId==='fix') return 'service';
  return 'product';
}

function buildItems(): UnifiedCatalogItem[] {
  return KAREEBU_CATALOG_SUBCATEGORIES.flatMap((subcategory)=>{
    const domainId=subcategory.domainId as KareebuDomainId;
    const pool=BRAND_POOLS[domainId] ?? ['Kareebu'];
    return namesFor(domainId,subcategory.title).map((name,index)=>{
      const id=`${subcategory.id}:item-${index+1}`;
      return {
        id,
        domainId,
        verticalId:subcategory.verticalId,
        categoryId:subcategory.categoryId,
        subcategoryId:subcategory.id,
        type:itemType(domainId),
        name,
        providerOrBrand:pool[stableHash(id)%pool.length]!,
        basePriceUGX:priceFor(domainId,subcategory.id,index),
        durationMinutes:['home-care','fix','dineout'].includes(domainId)?[60,90,120][index]:undefined,
        rating:Number((4.3+(stableHash(id+'rating')%7)/10).toFixed(1)),
        reviewCount:20+(stableHash(id+'reviews')%1800),
        provenance:'kareebu-seed' as const,
        searchTerms:[name,subcategory.title,domainId].map((value)=>value.toLowerCase()),
        metadata:{
          bookable:['home-care','fix','dineout'].includes(domainId),
          deliverable:['food','groceries','shops','electronics'].includes(domainId),
          requiresMerchantData:true as const,
          imageKey:`${domainId}-${subcategory.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,
        },
      };
    });
  });
}

export const KAREEBU_UNIFIED_ITEMS = buildItems();

export function catalogVerticals(domainId: KareebuDomainId) {
  return KAREEBU_CATALOG_VERTICALS.filter((node)=>node.domainId===domainId);
}

export function catalogCategories(verticalId: string) {
  return KAREEBU_CATALOG_CATEGORIES.filter((node)=>node.verticalId===verticalId);
}

export function catalogSubcategories(categoryId: string) {
  return KAREEBU_CATALOG_SUBCATEGORIES.filter((node)=>node.categoryId===categoryId);
}

export function catalogItemsForSubcategory(subcategoryId: string) {
  return KAREEBU_UNIFIED_ITEMS.filter((item)=>item.subcategoryId===subcategoryId);
}

export function catalogItemsForDomain(domainId: KareebuDomainId) {
  return KAREEBU_UNIFIED_ITEMS.filter((item)=>item.domainId===domainId);
}

export function catalogSearch(query: string, domains?: KareebuDomainId[]) {
  const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const allowed=domains?.length?new Set(domains):null;
  return KAREEBU_UNIFIED_ITEMS.filter((item)=>{
    if(allowed&&!allowed.has(item.domainId)) return false;
    return !terms.length||terms.every((term)=>item.searchTerms.some((value)=>value.includes(term)));
  }).slice(0,160);
}

export function cataloguePageDocument(input: {
  domainId: KareebuDomainId;
  verticalId?: string;
  categoryId?: string;
  subcategoryId?: string;
}) {
  const verticals=catalogVerticals(input.domainId);
  const activeVertical=input.verticalId??verticals[0]?.id;
  const categories=activeVertical?catalogCategories(activeVertical):[];
  const activeCategory=input.categoryId??categories[0]?.id;
  const subcategories=activeCategory?catalogSubcategories(activeCategory):[];
  const activeSubcategory=input.subcategoryId;
  const items=activeSubcategory
    ? catalogItemsForSubcategory(activeSubcategory)
    : KAREEBU_UNIFIED_ITEMS.filter((item)=>
        item.domainId===input.domainId &&
        (!activeVertical||item.verticalId===activeVertical) &&
        (!activeCategory||item.categoryId===activeCategory)
      ).slice(0,96);

  return {
    schema:'kareebu.catalog.page.v1',
    ...input,
    activeVertical,
    activeCategory,
    sections:[
      {type:'verticals',items:verticals},
      {type:'categories',items:categories},
      {type:'subcategories',items:subcategories},
      {type:'items',items},
    ],
  } as const;
}

if(KAREEBU_CATALOG_DOMAINS.length!==7) throw new Error('Domain count drift.');
if(KAREEBU_CATALOG_VERTICALS.length!==65) throw new Error('Vertical count drift.');
if(KAREEBU_CATALOG_CATEGORIES.length!==200) throw new Error('Category count drift.');
if(KAREEBU_CATALOG_SUBCATEGORIES.length!==690) throw new Error('Subcategory count drift.');
if(KAREEBU_UNIFIED_ITEMS.length!==2070) throw new Error('Item count drift.');
